ruleContent.content:
@css:.tab,.pagebar:nth-child(1),[id^="comment_"]@html
<js>
if(baseUrl.match(/page=\d+/)){
result=result
}else{
result="";
}
</js>
<js>
allpage=String(java.getString("@@class.num@text||class.pager.-2@text||class.pager.0@text")).match(/(\d+)/)?.[1];
result
.replace(/发表时间：/g,'\n⌚️')
.replace(/(№\d+)/g,'———————\n$1')
.replace(/<img src=".*?agree\.png">.*?numstr">([^<]+)<\/span>/g,'👍$1')
.replace(/<img.*?src=".*?agree_not\.png">.*?numstr">([^<]+)<\/span>/g,'👎$1')
