.replace(/）》\s+打分/g,' 打分')
.replace(/(№\d+|\[\d+楼\])\s*网友：/g,'$1 👤')
.replace(/№\d+.*?\s*⌚️\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}\s*·*\s*[👍\d]*\s*———————/g,'')
.replace(/№\d+.*?\s*⌚️\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}\s*·*\s*[👍\d]*$/,'')
.replace(
  /(⌚️\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})([\s\S]*?)(👍\d+|👎\d+|(👍\d+ 👎\d+))/g,
  "$1 $3$2"
);

ruleToc.chapterList:
$.chapterlist
<js>
if(result=="[]"){
allpage=String(java.getString("@@class.num@text||class.redtext@text||class.pager.-2@text||class.pager.0@text")).match(/(\d+)/)?.[1]??0;
result = [];
for(i=1;i<=allpage;i++){
result.push({
	chaptername:"第"+i+"页",
	url:baseUrl.replace(/&page=\d+/g,'')+"&page="+i
	});
}
result = JSON.stringify(result)
	}
result
</js>
